const Build* active() { return g_active; }
const Build* activate(std::uintptr_t mainBase, std::size_t textSize) {
    const Build* match = nullptr;
    for (const auto& build : kBuilds) {
        bool valid = true;
        for (const auto& site : build.identity) {
            if (site.offset < 0 || static_cast<std::size_t>(site.offset)+4 > textSize ||
                *reinterpret_cast<const std::uint32_t*>(mainBase+site.offset) != site.word) { valid = false; break; }
        }
        if (!valid) continue;
        if (match) { g_active = nullptr; return nullptr; }
        match = &build;
    }
    g_active = match;
    return match;
}
std::ptrdiff_t address(std::ptrdiff_t baseline121) {
    if (!g_active) return 0;
    for (const auto& row : kTranslations)
        if (row.old == baseline121) return row.mapped[static_cast<std::size_t>(g_active->version)];
    return g_active->version == Version::V121 ? baseline121 : 0;
}
bool newerRenderer() { return g_active && g_active->version >= Version::V140; }
